using System.Text.Json.Nodes;
using TouhouLastWorld;

internal sealed partial class RegressionSuite
{
    private void Scenario04()
    {
        var foodSeed = JsonNode.Parse(seed)!.AsObject();
        foodSeed["orb"]!["free"] = 3;
        foodSeed["orb"]!["purchased"] = 20;
        var foodDirectory = directory + "-food";
        var food = new OfflineServer(new JsonStateStore(foodDirectory), foodSeed.ToJsonString(), "offline://resources/");
        food.Dispatch("game_init");
        food.Dispatch("login");
        Check(food.Dispatch("lecture_room_food_addition").Status == 503, "food purchase requires master price");
        Check(food.Dispatch("lecture_room_food_addition", arguments: new(FoodPurchase: new(10, 2, 60, 1))).Status == 409 && food.Dispatch("lecture_room_food_addition", arguments: new(FoodPurchase: new(10, 2, 10, 20))).Status == 409, "both food balances checked before spending");
        var purchasedFood = food.Dispatch("lecture_room_food_addition", arguments: new(FoodPurchase: new(10, 2, 10, 5))).Body!["user_update"]!;
        Check(purchasedFood["phantasm_point"]!["points"]!.GetValue<int>() == 80 && purchasedFood["orb"]!["free"]!.GetValue<long>() == 0 && purchasedFood["orb"]!["purchased"]!.GetValue<long>() == 13 && purchasedFood["item"]!["item_list"]![0]!["num"]!.GetValue<int>() == 2, "food costs and inventory update together");
        food.Dispatch("lecture_room_food_addition", arguments: new(FoodPurchase: new(10, 1, 10, 5)));
        var foodReload = new OfflineServer(new JsonStateStore(foodDirectory), foodSeed.ToJsonString(), "offline://resources/");
        foodReload.Dispatch("game_init");
        var foodUser = foodReload.Dispatch("login").Body!["user"]!;
        Check(foodUser["item"]!["item_list"]![0]!["num"]!.GetValue<int>() == 3 && foodUser["phantasm_point"]!["points"]!.GetValue<int>() == 70 && JsonNode.DeepEquals(foodUser["lecture_room"], foodSeed["lecture_room"]), "food inventory persists without automatic distribution");
        Check(foodReload.Dispatch("lecture_room_food_addition", arguments: new(FoodPurchase: new(10, int.MaxValue, 0, 0))).Status == 409, "inventory overflow rejected");
        Console.WriteLine("Passed 5 food purchase checks.");
        Check(foodReload.Dispatch("lecture_room_food_distribution", arguments: new(FoodDistribution: new(10, 1, 4, 80, 100, 10))).Status == 409, "food distribution rejects insufficient inventory");
        var beforeDistribution = DateTimeOffset.UtcNow;
        var distributed = foodReload.Dispatch("lecture_room_food_distribution", arguments: new(FoodDistribution: new(10, 1, 2, 80, 100, 10))).Body!["user_update"]!;
        var foodState = distributed["lecture_room"]!["food"]!;
        var firstFinish = DateTimeOffset.Parse(foodState["food_list"]![0]!["add_effect_finish_time"]!.GetValue<string>(), System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.AssumeUniversal);
        Check(foodState["food_rest_value"]!.GetValue<int>() == 100 && distributed["item"]!["item_list"]![0]!["num"]!.GetValue<int>() == 1, "distribution caps food value and consumes requested items");
        Check((firstFinish - beforeDistribution).TotalMinutes is > 19.9 and < 20.1, "food effect duration uses minutes and quantity");
        foodReload.Dispatch("lecture_room_food_distribution", arguments: new(FoodDistribution: new(10, 1, 1, 80, 100, 10)));
        var foodAfterReload = new OfflineServer(new JsonStateStore(foodDirectory), foodSeed.ToJsonString(), "offline://resources/");
        foodAfterReload.Dispatch("game_init");
        var fedUser = foodAfterReload.Dispatch("login").Body!["user"]!;
        var effectsAfter = fedUser["lecture_room"]!["food"]!["food_list"]!.AsArray();
        var secondFinish = DateTimeOffset.Parse(effectsAfter[0]!["add_effect_finish_time"]!.GetValue<string>(), System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.AssumeUniversal);
        Check(effectsAfter.Count == 1 && secondFinish - firstFinish == TimeSpan.FromMinutes(10) && fedUser["item"]!["item_list"]![0]!["num"]!.GetValue<int>() == 0, "effect extension and consumed inventory persist");
        Check(fedUser["phantasm_point"]!["points"]!.GetValue<int>() == 70 && JsonNode.DeepEquals(fedUser["unit"], foodUser["unit"]), "distribution does not fabricate growth or charge purchase cost again");
        Console.WriteLine("Passed 5 food distribution checks.");
        var trainingSeed = JsonNode.Parse(seed)!.AsObject();
        trainingSeed["item"]!["item_list"] = new JsonArray(new JsonObject { ["item_id"] = 12, ["num"] = 2 });
        var startTrainingDirectory = directory + "-start-training";
        var startTraining = new OfflineServer(new JsonStateStore(startTrainingDirectory), trainingSeed.ToJsonString(), "offline://resources/");
        startTraining.Dispatch("game_init");
        var beforeTrainingStart = startTraining.Dispatch("login").Body!["user"]!;
        Check(startTraining.Dispatch("training_room_start").Status == 503 && startTraining.Dispatch("training_room_start", arguments: new(Training: new(1, 1, 12, 3, 2, 600))).Status == 400, "training requires definition and available slot number");
        Check(startTraining.Dispatch("training_room_start", arguments: new(Training: new(999, 1, 12, 1, 2, 600))).Status == 404 && startTraining.Dispatch("training_room_start", arguments: new(Training: new(1, 1, 99, 1, 2, 600))).Status == 409, "training requires owned unit and material");
        var startedTraining = startTraining.Dispatch("training_room_start", arguments: new(Training: new(1, 2, 12, 1, 2, 600))).Body!["user_update"]!;
        var trainingTask = startedTraining["training_room"]!["unit_list"]![0]!;
        Check(startedTraining["item"]!["item_list"]![0]!["num"]!.GetValue<int>() == 1 && trainingTask["skill_number"]!.GetValue<int>() == 2 && DateTime.Parse(trainingTask["training_finish_time"]!.GetValue<string>()) - DateTime.Parse(trainingTask["training_start_time"]!.GetValue<string>()) == TimeSpan.FromSeconds(600), "training consumes one material and stores duration in seconds");
        Check(startTraining.Dispatch("training_room_start", arguments: new(Training: new(1, 1, 12, 1, 2, 600))).Status == 409 && startTraining.Dispatch("training_room_start", arguments: new(Training: new(1, 1, 12, 2, 2, 600))).Status == 409, "training rejects duplicate slot and unit without another charge");
        var startTrainingReload = new OfflineServer(new JsonStateStore(startTrainingDirectory), trainingSeed.ToJsonString(), "offline://resources/");
        startTrainingReload.Dispatch("game_init");
        var trainingUser = startTrainingReload.Dispatch("login").Body!["user"]!;
        Check(trainingUser["item"]!["item_list"]![0]!["num"]!.GetValue<int>() == 1 && trainingUser["training_room"]!["unit_list"]!.AsArray().Count == 1 && JsonNode.DeepEquals(trainingUser["unit"], beforeTrainingStart["unit"]), "training persists without fabricated skill growth");
        Console.WriteLine("Passed 5 training start checks.");
        Check(startTrainingReload.Dispatch("training_room_shortened_finish_time", arguments: new(EntityId: 1, TrainingMaterials: [new(12, 1, 60), new(99, 1, 60)])).Status == 409, "training reduction validates every inventory entry before saving");
        Check(startTrainingReload.Dispatch("training_room_shortened_finish_time", arguments: new(EntityId: 1, TrainingMaterials: [new(12, 1, 60), new(12, 1, 60)])).Status == 400, "duplicate training materials rejected");
        var shortenedTraining = startTrainingReload.Dispatch("training_room_shortened_finish_time", arguments: new(EntityId: 1, TrainingMaterials: [new(12, 1, 60)])).Body!;
        Check(DateTime.Parse(trainingTask["training_finish_time"]!.GetValue<string>()) - DateTime.Parse(shortenedTraining["finish_time"]!.GetValue<string>()) == TimeSpan.FromSeconds(60) && shortenedTraining["user_update"]!["item"]!["item_list"]![0]!["num"]!.GetValue<int>() == 0, "training reduction returns exact updated deadline and consumes material once");
        var reducedTrainingReload = new OfflineServer(new JsonStateStore(startTrainingDirectory), trainingSeed.ToJsonString(), "offline://resources/");
        reducedTrainingReload.Dispatch("game_init");
        var reducedTrainingUser = reducedTrainingReload.Dispatch("login").Body!["user"]!;
        Check(reducedTrainingUser["training_room"]!["unit_list"]![0]!["training_finish_time"]!.GetValue<string>() == shortenedTraining["finish_time"]!.GetValue<string>() && reducedTrainingUser["item"]!["item_list"]![0]!["num"]!.GetValue<int>() == 0, "training deadline and material reduction persist together");
        var overTraining = new OfflineServer(new JsonStateStore(directory + "-over-training"), trainingSeed.ToJsonString(), "offline://resources/");
        overTraining.Dispatch("game_init");
        overTraining.Dispatch("login");
        overTraining.Dispatch("training_room_start", arguments: new(Training: new(1, 1, 12, 1, 2, 600)));
        overTraining.Dispatch("training_room_shortened_finish_time", arguments: new(EntityId: 1, TrainingMaterials: [new(12, 1, int.MaxValue)]));
        Check(overTraining.Dispatch("training_room_shortened_finish_time", arguments: new(EntityId: 1, TrainingMaterials: [new(12, 1, 60)])).Status == 409, "elapsed training cannot consume more materials");
        Console.WriteLine("Passed 5 training reduction checks.");
        var avatarSeed = JsonNode.Parse(seed)!.AsObject();
        avatarSeed["HeadListItemList"] = new JsonArray(new JsonObject { ["avatar_id"] = 1, ["is_preview"] = false, ["is_clear"] = true, ["filename"] = "IconA", ["title"] = "A", ["desc"] = "" }, new JsonObject { ["avatar_id"] = 2, ["is_preview"] = false, ["is_clear"] = true, ["filename"] = "IconB", ["title"] = "B", ["desc"] = "" }, new JsonObject { ["avatar_id"] = 3, ["is_preview"] = false, ["is_clear"] = false, ["filename"] = "IconC", ["title"] = "C", ["desc"] = "" });
        var avatarDirectory = directory + "-avatars";
        var avatars = new OfflineServer(new JsonStateStore(avatarDirectory), avatarSeed.ToJsonString(), "offline://resources/");
        avatars.Dispatch("game_init");
        avatars.Dispatch("login");
        Check(avatars.Dispatch("avatar/preview", arguments: new(Value: 99)).Status == 404, "unknown avatar cannot be marked read");
        Check(avatars.Dispatch("avatar/preview", arguments: new(Value: 1)).Body!["avatar_tips"]!.GetValue<int>() == 1 && avatars.Dispatch("avatar/preview", arguments: new(Value: 2)).Body!["avatar_tips"]!.GetValue<int>() == 0, "avatar unread indicator excludes locked entries");
        var avatarsReload = new OfflineServer(new JsonStateStore(avatarDirectory), avatarSeed.ToJsonString(), "offline://resources/");
        avatarsReload.Dispatch("game_init");
        var avatarUser = avatarsReload.Dispatch("login").Body!["user"]!;
        Check(avatarsReload.Dispatch("avatar/list").Body!["avatar_list"]![0]!["is_preview"]!.GetValue<bool>() && !avatarUser["isShowRedPoint"]!.GetValue<bool>() && avatarUser["avatar_id"]!.GetValue<int>() == 0, "avatar read state persists without changing selection");
        Console.WriteLine("Passed 3 avatar preview checks.");
        Check(avatarsReload.Dispatch("avatar/update", arguments: new(Value: 3)).Status == 403 && avatarsReload.Dispatch("avatar/update", arguments: new(Value: 99)).Status == 404, "avatar selection rejects locked and unknown entries");
        var selectedAvatar = avatarsReload.Dispatch("avatar/update", arguments: new(Value: 2)).Body!["user_update"]!;
        Check(selectedAvatar["avatar_id"]!.GetValue<int>() == 2 && selectedAvatar["avatar_filename"]!.GetValue<string>() == "IconB", "avatar selection returns saved ID and resource");
        var selectedAvatarReload = new OfflineServer(new JsonStateStore(avatarDirectory), avatarSeed.ToJsonString(), "offline://resources/");
        selectedAvatarReload.Dispatch("game_init");
        var selectedAvatarUser = selectedAvatarReload.Dispatch("login").Body!["user"]!;
        Check(selectedAvatarUser["avatar_id"]!.GetValue<int>() == 2 && selectedAvatarUser["avatar_title"]!.GetValue<string>() == "B" && !selectedAvatarUser["HeadListItemList"]![2]!["is_clear"]!.GetValue<bool>(), "avatar selection persists without unlocking other entries");
        Console.WriteLine("Passed 3 avatar selection checks.");
        var contactSeed = JsonNode.Parse(seed)!.AsObject();
        contactSeed["_local_friend_applications"] = new JsonArray(new JsonObject { ["public_id"] = "local-a" }, new JsonObject { ["public_id"] = "local-b" });
        var contactDirectory = directory + "-contacts";
        var contactServer = new OfflineServer(new JsonStateStore(contactDirectory), contactSeed.ToJsonString(), "offline://resources/");
        contactServer.Dispatch("game_init");
        contactServer.Dispatch("login");
        Check(contactServer.Dispatch("friend/refuse_apply", arguments: new(Value: 0, Text: "missing")).Status == 404 && contactServer.Dispatch("friend/refuse_apply", arguments: new(Value: 0)).Status == 400, "contact refusal validates single target");
        contactServer.Dispatch("friend/refuse_apply", arguments: new(Value: 0, Text: "local-a"));
        Check(contactServer.Dispatch("friend/apply_list").Body!["data"]!.AsArray().Count == 1 && contactServer.Dispatch("friend/list").Body!["request_tips"]!.GetValue<int>() == 1, "single refusal preserves remaining application and indicator");
        var contactsReload = new OfflineServer(new JsonStateStore(contactDirectory), contactSeed.ToJsonString(), "offline://resources/");
        contactsReload.Dispatch("game_init");
        contactsReload.Dispatch("login");
        Check(contactsReload.Dispatch("friend/apply_list").Body!["data"]![0]!["public_id"]!.GetValue<string>() == "local-b", "contact refusal persists");
        contactsReload.Dispatch("friend/refuse_apply", arguments: new(Value: 1));
        Check(contactsReload.Dispatch("friend/apply_list").Body!["data"]!.AsArray().Count == 0 && contactsReload.Dispatch("friend/list").Body!["request_tips"]!.GetValue<int>() == 0, "bulk refusal clears applications and indicator");
        Console.WriteLine("Passed 4 contact refusal checks.");
        var acceptDirectory = directory + "-accept-contact";
        var acceptContact = new OfflineServer(new JsonStateStore(acceptDirectory), contactSeed.ToJsonString(), "offline://resources/");
        acceptContact.Dispatch("game_init");
        acceptContact.Dispatch("login");
        Check(acceptContact.Dispatch("friend/accept_apply", arguments: new(Value: 1, Text: "missing")).Status == 404 && acceptContact.Dispatch("friend/accept_apply", arguments: new(Text: "local-a")).Status == 503, "contact acceptance requires existing application and capacity");
        Check(acceptContact.Dispatch("friend/accept_apply", arguments: new(Value: 1, Text: "local-a")).Status == 0 && acceptContact.Dispatch("friend/accept_apply", arguments: new(Value: 1, Text: "local-b")).Status == 20007, "contact capacity enforced without consuming blocked application");
        var acceptReload = new OfflineServer(new JsonStateStore(acceptDirectory), contactSeed.ToJsonString(), "offline://resources/");
        acceptReload.Dispatch("game_init");
        acceptReload.Dispatch("login");
        var acceptedFriends = acceptReload.Dispatch("friend/list").Body!["data"]!.AsArray();
        Check(acceptedFriends.Count == 1 && acceptedFriends[0]!["public_id"]!.GetValue<string>() == "local-a" && acceptReload.Dispatch("friend/apply_list").Body!["data"]![0]!["public_id"]!.GetValue<string>() == "local-b", "contact acceptance persists both sides of local transition");
        Check(acceptReload.Dispatch("friend/accept_apply", arguments: new(Value: 2, Text: "local-a")).Status == 404, "consumed application cannot create duplicate relationship");
        Console.WriteLine("Passed 4 contact acceptance checks.");
        Check(acceptReload.Dispatch("friend/info", arguments: new(Text: "missing")).Status == 404 && acceptReload.Dispatch("friend/info").Status == 400, "contact details require known local relation");
        Check(acceptReload.Dispatch("friend/info", arguments: new(Text: "local-a")).Body!["unit_get_count"]!.GetValue<int>() == 0, "contact details use empty counters when unavailable");
        var contactInfoSeed = JsonNode.Parse(seed)!.AsObject();
        contactInfoSeed["_local_friends"] = new JsonArray(new JsonObject { ["public_id"] = "local-known", ["unit_get_count"] = 7, ["quest_complete_count"] = 8, ["dispatch_complete_count"] = 9 });
        var contactInfoServer = new OfflineServer(new JsonStateStore(directory + "-contact-info"), contactInfoSeed.ToJsonString(), "offline://resources/");
        contactInfoServer.Dispatch("game_init");
        contactInfoServer.Dispatch("login");
        var knownContact = contactInfoServer.Dispatch("friend/info", arguments: new(Text: "local-known")).Body!;
        Check(knownContact["unit_get_count"]!.GetValue<int>() == 7 && knownContact["quest_complete_count"]!.GetValue<int>() == 8 && knownContact["dispatch_complete_count"]!.GetValue<int>() == 9, "contact details preserve stored counters");
        Console.WriteLine("Passed 3 contact detail checks.");
        var pointsSeed = JsonNode.Parse(seed)!.AsObject();
        pointsSeed["gold"] = 100;
        var pointsState = pointsSeed["unit"]!["unit_list"]![0]!["point_allocation_info"]!;
        pointsState["pa_type_1"] = 1;
        pointsState["pa_type_9"] = 2;
        pointsState["pa_points"] = 4;
        pointsState["pa_total_used_points"] = 12;
        var pointsDirectory = directory + "-points";
        var pointServer = new OfflineServer(new JsonStateStore(pointsDirectory), pointsSeed.ToJsonString(), "offline://resources/");
        pointServer.Dispatch("game_init");
        pointServer.Dispatch("login");
        var resetPoints = pointServer.Dispatch("reset_point_allocation", arguments: new(PointReset: new(1, 200, false))).Body!["user_update"]!;
        Check(resetPoints["gold"]!.GetValue<int>() == 100 && resetPoints["unit"]!["unit_list"]![0]!["point_allocation_info"]!["pa_points"]!.GetValue<int>() == 16, "first reset returns used points without charge");
        pointServer.Dispatch("reset_point_allocation", arguments: new(PointReset: new(1, 200, false)));
        var pointReload = new OfflineServer(new JsonStateStore(pointsDirectory), pointsSeed.ToJsonString(), "offline://resources/");
        pointReload.Dispatch("game_init");
        var resetUser = pointReload.Dispatch("login").Body!["user"]!;
        var resetState = resetUser["unit"]!["unit_list"]![0]!["point_allocation_info"]!;
        Check(resetState["pa_points"]!.GetValue<int>() == 16 && resetState["pa_total_used_points"]!.GetValue<int>() == 0 && resetState["pa_type_9"]!.GetValue<int>() == 0 && resetState["is_pa_reset_not_free"]!.GetValue<int>() == 1 && resetUser["gold"]!.GetValue<int>() == 100, "reset persists and repeated empty reset does not refund again");
        pointsState["is_pa_reset_not_free"] = 1;
        var paidPoints = new OfflineServer(new JsonStateStore(directory + "-paid-points"), pointsSeed.ToJsonString(), "offline://resources/");
        paidPoints.Dispatch("game_init");
        paidPoints.Dispatch("login");
        Check(paidPoints.Dispatch("reset_point_allocation", arguments: new(PointReset: new(1, 101, false))).Status == 409, "paid reset rejects insufficient balance");
        var paidReset = paidPoints.Dispatch("reset_point_allocation", arguments: new(PointReset: new(1, 30, false))).Body!["user_update"]!;
        Check(paidReset["gold"]!.GetValue<int>() == 70 && paidReset["unit"]!["unit_list"]![0]!["point_allocation_info"]!["pa_points"]!.GetValue<int>() == 16, "paid reset changes points and gold together");
        var freePoints = new OfflineServer(new JsonStateStore(directory + "-free-points"), pointsSeed.ToJsonString(), "offline://resources/");
        freePoints.Dispatch("game_init");
        freePoints.Dispatch("login");
        Check(freePoints.Dispatch("reset_point_allocation", arguments: new(PointReset: new(1, 200, true))).Body!["user_update"]!["gold"]!.GetValue<int>() == 100, "free reset setting overrides repeat cost");
        Console.WriteLine("Passed 5 point reset checks.");
    }
}
